/* Multi-select setup, timed session, feedback and local results. */
function quizRead(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let quizState={view:'menu',config:quizDefaultConfig()};
let quizSession=quizRead('gaku-quiz-session-v1',null),quizPoolCache=[],quizBankError='',quizBankPromise=null,quizClock=null,quizExitAction=null;
if(!quizSession||!Array.isArray(quizSession.questions)||quizSession.questions.length>40||!Array.isArray(quizSession.responses)||!Number.isFinite(quizSession.deadline))quizSession=null;
function getQuizRoute(){return {view:quizState.view,config:JSON.parse(JSON.stringify(quizState.config)),runId:quizSession?.id||null}}
function resetQuizRoute(){if(!quizIsActive())quizState={view:'menu',config:quizDefaultConfig()}}
function restoreQuizRoute(r){if(!r||typeof r!=='object'){resetQuizRoute();return}const c={...quizDefaultConfig(),...r.config};if(!QUIZ_TYPES[c.type])c.type='kana';if(!['Hiragana','Katakana'].includes(c.script))c.script='Hiragana';for(const key of ['letters','categories','subs','pages'])c[key]=Array.isArray(c[key])?quizUnique(c[key].filter(x=>typeof x==='string').slice(0,5000)):[];c.count=quizRequestedCount(c.type,c.count,c.type==='bunpo'?10:20);if(c.type==='kana'&&!['play','result'].includes(r.view))c.letters=quizExpandKanaSelection(c);if(c.type==='mixed')c.count=40;quizState={view:['menu','script','letters','mode','categories','subs','pages','confirm','play','result'].includes(r.view)?r.view:'menu',config:c};if(['play','result'].includes(quizState.view)){if(!quizSession||r.runId!==quizSession.id)quizState.view='menu';else if(quizSession.status!=='active')quizState.view='result'}quizPoolCache=[]}
function quizPersist(){try{if(quizSession)localStorage.setItem('gaku-quiz-session-v1',JSON.stringify(quizSession))}catch{toast('Hasil belum bisa disimpan: penyimpanan perangkat penuh.')}}
function quizRemember(){if(page==='Quiz')history.replaceState(appRoute(),'')}
function quizMove(view,replace=false){quizState.view=view;quizPoolCache=[];if(replace)history.replaceState(appRoute(),'');else pushRoute();updateScreen()}
function quizRefresh(){const handler=document.activeElement?.getAttribute?.('onclick');quizRemember();render();if(handler)[...document.querySelectorAll('button')].find(b=>b.getAttribute('onclick')===handler)?.focus({preventScroll:true})}
function quizIsActive(){return !!quizSession&&quizSession.status==='active'&&page==='Quiz'&&quizState.view==='play'}
const quizBankLoads={},quizBankErrors={};let quizPoolLevel='';
function quizCurrentBankError(){return quizBankErrors[quizKotobaLevel()]||''}
function quizEnsureBank(){const level=quizKotobaLevel();if(quizActiveBunpoBank()||quizBankLoads[level])return quizBankLoads[level];quizBankError='';quizBankErrors[level]='';const url=level==='N4'?'assets/quiz/bunpo-n4-bank.json':'assets/quiz/bunpo-bank.json';const pending=fetch(url).then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(data=>{if(!Array.isArray(data)||data.length!==(level==='N4'?6900:2580)||data.some(q=>(q.level||'N5')!==level))throw Error('Data tidak lengkap');if(level==='N4')quizBunpoN4Bank=data;else quizBunpoBank=data;quizPoolCache=[]}).catch(()=>{quizBankErrors[level]='Bank soal belum berhasil dimuat. Periksa koneksi, lalu coba lagi.';if(quizKotobaLevel()===level)quizBankError=quizBankErrors[level]}).finally(()=>{delete quizBankLoads[level];if(quizBankPromise===pending)quizBankPromise=null;if(page==='Quiz'&&!quizIsActive())render()});quizBankLoads[level]=pending;quizBankPromise=pending;return pending}
function quizRetryBank(){quizEnsureBank();render()}
function quizChooseType(type){if(!QUIZ_TYPES[type])return;if(quizSession?.status==='active'){quizFinish(quizRemaining()<=0?'time':'abandoned');}quizState.config={...quizDefaultConfig(),type,mode:type==='bunpo'?'cloze':type==='kanji'?'kanji-meaning':'jp-id',count:type==='mixed'?40:10};quizMove(type==='kana'?'script':type==='mixed'?'confirm':'mode');if(quizTypeAvailable(type)&&(type==='bunpo'||type==='mixed'))quizEnsureBank()}
function quizSelectScript(script){quizState.config.script=script;quizState.config.letters=[];quizMove('letters')}
function quizSelectMode(mode){const c=quizState.config;if(!QUIZ_MODES[c.type]?.some(([m])=>m===mode))return;c.mode=mode;quizRefresh()}
function quizSelectReading(kind){if(!['on','kun'].includes(kind))return;quizState.config.reading=kind;quizRefresh()}
function quizToggle(key,id){const c=quizState.config;if(!['letters','categories','subs','pages'].includes(key))return;const arr=c[key];c[key]=arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];if(key==='categories'){const allowed=new Set(quizSubs(c.type,c.categories).map(s=>s.id));c.subs=c.subs.filter(s=>allowed.has(s));c.pages=[]}if(key==='subs')c.pages=[];quizPoolCache=[];quizRefresh()}
function quizAll(key,ids){const c=quizState.config;if(!['letters','categories','subs','pages'].includes(key))return;c[key]=ids.every(id=>c[key].includes(id))?c[key].filter(id=>!ids.includes(id)):quizUnique([...c[key],...ids]);if(key==='categories'){c.subs=c.subs.filter(s=>quizSubs(c.type,c.categories).some(x=>x.id===s));c.pages=[]}if(key==='subs')c.pages=[];quizPoolCache=[];quizRefresh()}
function quizAllCurrent(key,group){const c=quizState.config;const ids=key==='letters'?quizKanaItems(c.script).filter(e=>!group||e.group===group).map(e=>e.id):key==='categories'?quizCategories(c.type).map(e=>e.id):key==='subs'?quizSubs(c.type,c.categories).map(e=>e.id):quizWordPages(c).map(e=>e.id);quizAll(key,ids)}
function quizSetCount(n){const c=quizState.config;c.count=quizRequestedCount(c.type,n,quizConfirmedPool().length);quizRefresh()}
function quizTogglePack(id){const pack=quizKanaPacks(quizState.config.script).find(p=>p.id===id);if(pack)quizAll('letters',pack.ids)}
function quizPackHTML(pack){const c=quizState.config,selected=pack.ids.every(id=>c.letters.includes(id));return '<button class="quiz-pick quiz-kana-pack '+(selected?'is-chosen':'')+'" aria-pressed="'+selected+'" aria-label="Paket '+esc(pack.label)+' · '+pack.ids.length+' huruf" onclick="quizTogglePack(\''+pack.id+'\')"><span><strong lang="ja">'+esc(pack.kana)+'</strong><b>'+esc(pack.label)+'</b><small>'+pack.ids.length+' huruf</small></span><i aria-hidden="true">'+(selected?'✓':'+')+'</i></button>'}

function quizSetupNext(){const c=quizState.config,v=quizState.view;if(v==='mode'){quizMove('categories');return}if(v==='letters'&&c.letters.length>=5){quizMove('confirm');return}if(v==='categories'&&c.categories.length){quizMove(c.type==='kanji'?'confirm':'subs');return}if(v==='subs'&&c.subs.length){quizMove(c.type==='kotoba'?'pages':'confirm');return}if(v==='pages'&&c.pages.length)quizMove('confirm')}
function quizConfirmedPool(){if(!quizPoolCache.length||quizPoolLevel!==quizKotobaLevel()){quizPoolCache=quizPool(quizState.config);quizPoolLevel=quizKotobaLevel()}return quizPoolCache}
function quizHeader(title,subtitle){return '<div class="quiz-page-head"><button class="round" onclick="appBack()" aria-label="Kembali">‹</button><div><span class="quiz-eyebrow">TAMAN LATIHAN · '+esc(QUIZ_TYPES[quizState.config.type]?.name||'Kuis')+'</span><h1>'+esc(title)+'</h1><p>'+esc(subtitle)+'</p></div></div>'}
function quizChip(key,id,label,detail='',symbol=''){const chosen=quizState.config[key].includes(id);return '<button class="quiz-pick '+(chosen?'is-chosen':'')+'" aria-pressed="'+chosen+'" onclick="quizToggle(\''+key+'\',\''+esc(id)+'\')">'+(symbol?'<strong class="quiz-pick-symbol">'+esc(symbol)+'</strong>':'')+'<span><b>'+esc(label)+'</b>'+(detail?'<small>'+esc(detail)+'</small>':'')+'</span><i aria-hidden="true">'+(chosen?'✓':'+')+'</i></button>'}
function quizAllButton(key,label='Pilih semua',group=''){return '<button class="quiz-all" onclick="quizAllCurrent(\''+key+'\',\''+group+'\')">'+esc(label)+'</button>'}
function quizNextButton(enabled,label='Lanjut →'){return '<div class="quiz-setup-footer"><span>'+esc(quizSelectionCount())+'</span><button class="primary" onclick="quizSetupNext()" '+(!enabled?'disabled':'')+'>'+label+'</button></div>'}
function quizSelectionCount(){const c=quizState.config;const v=quizState.view;return v==='letters'?quizKanaPacks(c.script).filter(p=>p.ids.every(id=>c.letters.includes(id))).length+' paket · '+c.letters.length+' huruf':v==='categories'?c.categories.length+' kategori dipilih':v==='subs'?c.subs.length+' subkategori dipilih':v==='pages'?c.pages.length+' halaman dipilih':'Pilih sesuai tujuan belajarmu.'}
function quizResume(){if(!quizSession||quizSession.status!=='active')return;quizState.config=JSON.parse(JSON.stringify(quizSession.config));quizMove('play');quizSyncLifecycle()}
function quizMenu(){return title('Quiz','Sedikit tantangan, banyak yang bisa kamu pelajari.')+(quizSession?.status==='active'?'<div class="quiz-resume"><p>Ada sesi yang belum selesai. Waktunya tetap berjalan sejak terakhir dibuka.</p><button class="primary" onclick="quizResume()">Lanjutkan sesi →</button></div>':'')+'<section class="quiz-welcome"><div><span class="quiz-eyebrow">SIAP MENCOBA?</span><h2>Latihan sesuai<br>pilihanmu.</h2><p>Pilih materi, atur cakupannya, lalu kumpulkan jawaban benar.</p></div><span class="quiz-mascot" aria-hidden="true">✿<small>がんばろう</small></span></section><div class="quiz-type-grid">'+Object.entries(QUIZ_TYPES).map(([id,t])=>'<button class="quiz-type quiz-'+t.color+'" onclick="quizChooseType(\''+id+'\')"><span class="quiz-type-symbol">'+t.symbol+'</span><div><h2>'+t.name+'</h2><p>'+t.description+'</p></div><span aria-hidden="true">↗</span></button>').join('')+'</div><div class="quiz-small-rules"><span>◷ 60 detik</span><span>♡ 3 nyawa</span><span>✓ +3 dtk · × −5 dtk</span></div>'}
function quizModeScreen(){const c=quizState.config;return quizHeader('Mau latihan yang mana?','Pilih satu jenis soal untuk sesi ini.')+'<div class="quiz-choice-list">'+QUIZ_MODES[c.type].map(([id,label])=>'<button class="quiz-pick '+(c.mode===id?'is-chosen':'')+'" aria-pressed="'+(c.mode===id)+'" onclick="quizSelectMode(\''+id+'\')"><span><b>'+label+'</b></span><i aria-hidden="true">'+(c.mode===id?'✓':'○')+'</i></button>').join('')+'</div>'+(c.type==='kanji'&&c.mode.includes('reading')?'<section class="quiz-reading-choice"><h2>Bacaan mana yang dilatih?</h2><p>Kun’yomi ditampilkan dengan okurigana dalam tanda kurung bila ada.</p><div class="quiz-segment" role="group" aria-label="Jenis bacaan">'+[['on',"On’yomi"],['kun',"Kun’yomi"]].map(([id,n])=>'<button aria-pressed="'+(c.reading===id)+'" onclick="quizSelectReading(\''+id+'\')">'+n+'</button>').join('')+'</div></section>':'')+quizNextButton(true)}
const quizKanaOpen={Hiragana:{},Katakana:{}};
function quizKanaDisclosure(id,open){quizKanaOpen[quizState.config.script][id]=open}
function quizLettersScreen(){const c=quizState.config,packs=quizKanaPacks(c.script);return quizHeader('Pilih paket hurufmu.','Buka kelompok, lalu pilih satu atau beberapa paket. Gabungkan hingga minimal 5 huruf.')+'<div class="quiz-section-line"><h2>'+c.script+'</h2>'+quizAllButton('letters')+'</div>'+Object.entries(KANA_GROUPS).map(([id,g])=>{const selected=quizKanaItems(c.script).filter(e=>e.group===id&&c.letters.includes(e.id)).length;return '<details class="quiz-kana-group quiz-kana-disclosure" '+(quizKanaOpen[c.script][id]?'open':'')+' ontoggle="quizKanaDisclosure(\''+id+'\',this.open)"><summary><span><strong>'+g.name+'</strong><small>'+g.count+' huruf'+(selected?' · '+selected+' dipilih':'')+'</small></span><i aria-hidden="true"></i></summary><div class="quiz-kana-content"><div class="quiz-section-line">'+quizAllButton('letters','Semua '+g.name,id)+'</div><div class="quiz-pack-grid">'+packs.filter(p=>p.group===id).map(quizPackHTML).join('')+'</div></div></details>'}).join('')+quizNextButton(c.letters.length>=5,'Lihat konfirmasi →')}


function quizCategoriesScreen(){const c=quizState.config;return quizHeader('Pilih kategori.','Kamu boleh memilih lebih dari satu kategori.')+'<div class="quiz-section-line"><h2>Materi '+QUIZ_TYPES[c.type].name+'</h2>'+quizAllButton('categories')+'</div><div class="quiz-pick-grid">'+quizCategories(c.type).map(e=>quizChip('categories',e.id,e.name,e.count+(c.type==='bunpo'?' subkategori':' materi'))).join('')+'</div>'+quizNextButton(c.categories.length>0,c.type==='kanji'?'Lihat konfirmasi →':'Pilih subkategori →')}
function quizSubsScreen(){const c=quizState.config,subs=quizSubs(c.type,c.categories);return quizHeader('Persempit pilihanmu.','Pilih satu atau beberapa subkategori yang ingin dilatih.')+'<div class="quiz-section-line"><h2>Subkategori</h2>'+quizAllButton('subs')+'</div>'+quizCategories(c.type).filter(x=>c.categories.includes(x.id)).map(cat=>'<section class="quiz-sub-group"><h3>'+esc(cat.name)+'</h3><div class="quiz-pick-grid">'+subs.filter(s=>s.category===cat.id).map(s=>quizChip('subs',s.id,s.name,s.count+(c.type==='bunpo'?' soal · 15 per jenis':' kata'))).join('')+'</div></section>').join('')+quizNextButton(c.subs.length>0,c.type==='kotoba'?'Pilih halaman →':'Lihat konfirmasi →')}
function quizPagesScreen(){const c=quizState.config,pages=quizWordPages(c);return quizHeader('Halaman mana yang sudah dipelajari?','Tiap halaman berisi sampai 15 kata. Halaman dengan kurang dari 5 kata tidak ditampilkan.')+'<div class="quiz-section-line"><h2>Halaman kosakata</h2>'+quizAllButton('pages')+'</div>'+quizSubs(c.type,c.categories).filter(s=>c.subs.includes(s.id)).map(s=>{const group=pages.filter(p=>p.sub===s.id);return '<section class="quiz-sub-group"><h3>'+esc(s.name)+'</h3>'+(group.length?'<div class="quiz-pick-grid">'+group.map(p=>quizChip('pages',p.id,'Halaman '+p.number,p.items.length+' kata · '+p.items.slice(0,3).map(w=>w.jp).join('、'))).join('')+'</div>':'<p class="quiz-empty">Belum ada halaman dengan minimal 5 kata pada subkategori ini.</p>')+'</section>'}).join('')+quizNextButton(c.pages.length>0,'Lihat konfirmasi →')}
function quizBankLoading(){return '<section class="quiz-empty" role="status"><span>📖</span><h2>'+ (quizCurrentBankError()?'Belum bisa membuka soal':'Menyiapkan bank soal…')+'</h2><p>'+esc(quizCurrentBankError()||'Sebentar, kita siapkan latihan Bunpo untukmu.')+'</p>'+(quizCurrentBankError()?'<button class="primary" onclick="quizRetryBank()">Coba lagi</button>':'')+'</section>'}
function quizScopeHTML(c,pool){if(c.type==='mixed')return '<div class="quiz-scope-grid">'+Object.values(QUIZ_TYPES).slice(0,4).map(t=>'<div><b>'+t.symbol+' '+t.name+'</b><span>10 soal</span></div>').join('')+'</div><p>Kana: Hiragana dan Katakana. Kanji: arti dua arah. Kotoba: Jepang dan arti dua arah. Bunpo: campuran empat jenis soal dari materi '+esc(quizKotobaLevel())+'.</p>';const cats=quizCategories(c.type).filter(x=>c.categories.includes(x.id)).map(x=>x.name);const labels=c.type==='kana'?[c.script,...Object.keys(KANA_GROUPS).filter(g=>quizKanaItems(c.script).some(e=>e.group===g&&c.letters.includes(e.id))).map(g=>KANA_GROUPS[g].name)]:[...cats,...quizSubs(c.type,c.categories).filter(s=>c.subs.includes(s.id)).map(s=>s.name)];return '<div class="quiz-scope-tags">'+labels.map(t=>'<span>'+esc(t)+'</span>').join('')+'</div>'+(c.type==='kotoba'?'<p>'+c.pages.length+' halaman dipilih · urutan tiap halaman mengikuti subkategorinya.</p>':'')+'<details class="quiz-preview"><summary>Lihat cakupan materi · '+pool.length+' '+(c.type==='bunpo'?'soal':'materi')+'</summary><ul>'+pool.map(q=>'<li><b>'+esc(q.display)+'</b>'+(c.type==='kana'?'':q.sourceLabel?'<small>'+esc(q.sourceLabel)+'</small>':'')+'</li>').join('')+'</ul></details>'}
function quizConfirmScreen(){const c=quizState.config;if((c.type==='bunpo'||c.type==='mixed')&&!quizActiveBunpoBank()){if(!quizCurrentBankError())quizEnsureBank();return quizHeader('Sebentar lagi mulai.','Periksa pilihan dan aturan kuismu.')+quizBankLoading()}const pool=c.type==='mixed'?[]:quizConfirmedPool();const choices=quizCountChoices(c.type,pool.length),max=quizCountLimit(c.type,pool.length);if(c.type!=='mixed')c.count=quizRequestedCount(c.type,c.count,pool.length);const actual=quizActualCount(c.type,c.count,pool.length),valid=c.type==='mixed'||pool.length>=5;return quizHeader('Sudah siap mencoba?','Periksa materi pilihanmu sebelum waktu dimulai.')+'<section class="quiz-confirm-card"><span class="quiz-eyebrow">SESI LATIHANMU</span><h2>'+QUIZ_TYPES[c.type].name+(c.type==='kana'?' · '+c.script:'')+'</h2><p class="quiz-confirm-mode">'+esc(c.type==='mixed'?'Empat materi, satu tantangan':c.type==='kana'?'Kana → romaji':QUIZ_MODES[c.type].find(([m])=>m===c.mode)?.[1]||'')+(c.type==='kanji'&&c.mode.includes('reading')?' · '+(c.reading==='on'?"On’yomi":"Kun’yomi"):'')+'</p>'+quizScopeHTML(c,pool)+(c.type==='mixed'?'<div class="quiz-count-fixed"><b>40 soal</b><span>10 soal untuk setiap materi</span></div>':valid?'<fieldset class="quiz-count-picker"><legend>Berapa soal?</legend><div class="quiz-count-buttons">'+choices.map(n=>'<button aria-pressed="'+(c.count===n)+'" onclick="quizSetCount('+n+')">'+n+'</button>').join('')+'<button class="quiz-count-add" aria-label="Tambah 5 soal" onclick="quizSetCount('+(c.count+5)+')" '+(c.count>=max?'disabled':'')+'>+</button></div><p>Pilihan bertahap 5 · batas pilihan '+max+' soal.</p><p class="quiz-count-actual">'+(c.count>=pool.length?'Semua <b>'+actual+' materi</b> akan diujikan.':'<b>'+actual+' soal</b> dipilih acak dari '+pool.length+' materi.')+(c.count>pool.length?' Pilihanmu '+c.count+' soal; yang tersedia '+pool.length+'. Tidak ada soal yang diulang.':'')+'</p></fieldset>':'<p class="quiz-empty">Materi yang memenuhi pilihan ini hanya '+pool.length+'. Pilih lebih banyak materi agar tersedia minimal 5 soal.</p>')+'</section><section class="quiz-rules"><h2>Aturan kecil sebelum mulai</h2><ul><li><b>60 detik</b> untuk seluruh sesi, bukan setiap soal.</li><li>Benar: <b>+3 detik</b>. Salah: <b>−5 detik dan −1 nyawa</b>.</li><li>Kamu punya <b>3 nyawa</b>. Waktu atau nyawa habis berarti game over.</li><li>Warna jawaban ditandai selama <b>2 detik</b>, lalu soal berganti otomatis. Hitungan waktu berhenti selama jeda ini.</li><li>Soal dipilih acak tanpa mengulang soal yang sama dalam satu sesi.</li></ul></section><button class="primary quiz-start" onclick="quizStart()" '+(!valid?'disabled':'')+'>Mulai '+actual+' soal →</button><p class="quiz-local-note">Hasil tersimpan di perangkat ini. Login dan sinkronisasi Google belum aktif.</p>'}
function quizStart(){const c=quizState.config;if(!quizTypeAvailable(c.type)){toast('Level kuis belum tersedia.');return;}if((c.type==='bunpo'||c.type==='mixed')&&!quizActiveBunpoBank())return;const deck=quizMakeDeck(c,c.type==='mixed'?[]:quizConfirmedPool());if(!deck.length){toast('Pilih materi yang cukup untuk minimal 5 soal.');return}const now=Date.now();quizSession={id:'q-'+now+'-'+Math.random().toString(36).slice(2,9),type:c.type,config:{...JSON.parse(JSON.stringify(c)),level:quizKotobaLevel()},questions:deck,index:0,lives:3,correct:0,responses:[],status:'active',reason:'',phase:'question',deadline:now+60000,startedAt:now,feedback:null};quizPersist();quizMove('play');quizSyncLifecycle()}
function quizRemaining(now=Date.now()){if(!quizSession)return 0;return Math.max(0,quizSession.phase==='feedback'?(now<=quizSession.feedback.until?quizSession.feedback.remaining:(quizSession.feedback.until+quizSession.feedback.remaining*1000-now)/1000):(quizSession.deadline-now)/1000)}
function quizAnswer(index){if(!quizIsActive()||quizSession.phase!=='question')return;const q=quizSession.questions[quizSession.index];if(!Number.isInteger(index)||!q.options||index<0||index>=q.options.length)return;quizResolve(index===q.answer,q.options[index],index)}
function quizPickPiece(index){if(!quizIsActive()||quizSession.phase!=='question')return;const q=quizSession.questions[quizSession.index];if(q.mode!=='order'||!q.pieces.some(p=>p.index===index)||q.picked.includes(index))return;q.picked.push(index);quizPersist();quizRenderPlay()}
function quizUndoPiece(){if(!quizIsActive()||quizSession.phase!=='question')return;const q=quizSession.questions[quizSession.index];q.picked.pop();quizPersist();quizRenderPlay()}
function quizCheckOrder(){if(!quizIsActive()||quizSession.phase!=='question')return;const q=quizSession.questions[quizSession.index];if(q.mode!=='order'||q.picked.length!==q.pieces.length)return;const chosen=q.chunks[0]+q.picked.map(i=>q.chunks[i]).join('')+'。';quizResolve(quizNorm(chosen)===quizNorm(q.answerText),chosen,null)}
function quizResolve(correct,chosen,index){const now=Date.now(),remaining=quizRemaining(now);if(remaining<=0){quizFinish('time');return}const s=quizSession,q=s.questions[s.index];if(s.responses.some(a=>a.questionIndex===s.index))return;if(correct)s.correct++;else s.lives--;const adjusted=Math.max(0,remaining+(correct?3:-5));s.responses.push({questionIndex:s.index,questionId:q.id,correct,chosen,index,answer:q.mode==='order'?q.answerText:q.options[q.answer],explanation:q.explanation,display:q.display,type:q.type});s.phase='feedback';s.feedback={correct,chosen,remaining:adjusted,until:now+2000,terminal:s.lives<=0?'lives':adjusted<=0?'time':s.index===s.questions.length-1?'completed':''};quizPersist();quizRenderPlay()}
function quizAdvance(now=Date.now()){const s=quizSession;if(!s||s.phase!=='feedback'||now<s.feedback.until)return;if(s.feedback.terminal){quizFinish(s.feedback.terminal);return}s.deadline=s.feedback.until+s.feedback.remaining*1000;s.feedback=null;s.phase='question';s.index++;quizPersist();if(s.deadline<=now){quizFinish('time');return}quizRenderPlay();window.scrollTo?.({top:0,behavior:'instant'})}
function quizTick(){if(!quizIsActive()){if(quizClock)clearInterval(quizClock);quizClock=null;return}if(quizSession.phase==='feedback')quizAdvance();else if(quizRemaining()<=0)quizFinish('time');const timer=document.getElementById('quiz-clock');if(timer){const n=Math.ceil(quizRemaining());timer.textContent=n+' dtk';timer.classList.toggle('is-low',n<=10)}}
function quizSyncLifecycle(){if(quizIsActive()){if(!quizClock)quizClock=setInterval(quizTick,200);quizTick()}else{if(quizClock)clearInterval(quizClock);quizClock=null}}
function quizFinish(reason){const s=quizSession;if(!s||s.status!=='active')return;s.status=reason==='completed'?'completed':reason==='abandoned'?'abandoned':'gameover';s.reason=reason;s.endedAt=Date.now();s.remaining=quizRemaining();s.phase='done';if(quizClock)clearInterval(quizClock);quizClock=null;if(quizExitAction){quizExitAction=null;closeModal()}const record={type:'Quiz '+QUIZ_TYPES[s.type].name,detail:s.correct+'/'+s.questions.length+' benar · '+(reason==='completed'?'Selesai':reason==='abandoned'?'Dihentikan':reason==='lives'?'Nyawa habis':'Waktu habis'),time:new Date(s.endedAt).toISOString(),quiz:{id:s.id,correct:s.correct,total:s.questions.length,answered:s.responses.length,lives:s.lives,status:s.status,reason:s.reason,responses:s.responses}};if(!historyData.some(h=>h.quiz?.id===s.id)){historyData.unshift(record);historyData=historyData.slice(0,40);try{localStorage.setItem('gaku-ui-history',JSON.stringify(historyData))}catch{toast('Riwayat belum bisa disimpan di perangkat ini.')}}quizPersist();quizState.view='result';quizRemember();if(page==='Quiz')updateScreen()}
function quizOptionLabel(q,text){if(q.type!=='kotoba'||q.mode!=='id-jp')return text;const word=quizKotobaData().find(e=>e.jp===text);return word?quizWordLabel(word):text}
function quizQuestionHTML(){const s=quizSession,q=s.questions[s.index],feedback=s.phase==='feedback',last=s.responses.at(-1);return '<div class="quiz-question-context"><span>'+esc(QUIZ_TYPES[q.type].name)+'</span><small>'+esc(q.sourceLabel||'Latihan Bunpo')+'</small></div><h2>'+esc(q.prompt)+'</h2>'+(q.translation&&q.mode==='cloze'?'<p class="quiz-question-translation">'+esc(q.translation)+'</p>':'')+'<div class="quiz-question-text '+(q.type==='kana'||(q.type==='kanji'&&!q.mode.startsWith('meaning'))?'quiz-large-character':'')+'" '+(q.type==='kana'?'lang="ja"':'')+'>'+esc(q.display)+'</div>'+(q.type==='kotoba'&&q.mode==='jp-id'&&q.kana&&q.kana!==q.display?'<p class="quiz-kotoba-reading" lang="ja">'+esc(q.kana)+'</p>':'')+(q.mode==='order'?'<p class="quiz-order-hint">Susun potongan setelah <b lang="ja">'+esc(q.chunks[0])+'</b>. Ikuti urutan pola yang dipelajari.</p><div class="quiz-order-tray" aria-label="Kalimat yang disusun"><span class="quiz-fixed">'+esc(q.chunks[0])+'</span>'+q.picked.map(i=>'<span>'+esc(q.chunks[i])+'</span>').join('')+'</div><div class="quiz-order-pieces" role="group" aria-label="Potongan kata acak">'+q.pieces.map(p=>'<button '+(feedback||q.picked.includes(p.index)?'disabled':'')+' onclick="quizPickPiece('+p.index+')">'+esc(p.text)+'</button>').join('')+'</div><div class="quiz-order-controls"><button class="quiz-all" onclick="quizUndoPiece()" '+(feedback||!q.picked.length?'disabled':'')+'>↶ Urungkan</button><button class="primary" onclick="quizCheckOrder()" '+(feedback||q.picked.length!==q.pieces.length?'disabled':'')+'>Periksa jawaban</button></div>':'<div class="quiz-answer-grid">'+q.options.map((o,i)=>'<button '+(feedback?'disabled':'')+' onclick="quizAnswer('+i+')" class="'+(feedback&&i===q.answer?'is-correct':feedback&&i===last.index?'is-wrong':'')+'"><span>'+String.fromCharCode(65+i)+'</span><b>'+esc(quizOptionLabel(q,o))+'</b>'+(feedback&&i===q.answer?'<em>✓</em>':'')+'</button>').join('')+'</div>')}
function quizPlayScreen(){const s=quizSession;if(!s)return quizMenu();return '<section class="quiz-game"><div class="quiz-game-top"><button class="round" onclick="quizGuard(()=>appBack())" aria-label="Keluar dari kuis">×</button><span>Soal '+(s.index+1)+' / '+s.questions.length+'</span><div class="quiz-lives" aria-label="'+s.lives+' nyawa tersisa">'+Array.from({length:3},(_,i)=>'<span class="'+(i<s.lives?'':'is-lost')+'" aria-hidden="true">♥</span>').join('')+'</div></div><div class="quiz-clock-row"><span>Waktu sesi</span><b id="quiz-clock" role="timer" aria-live="off">'+Math.ceil(quizRemaining())+' dtk</b></div><div id="quiz-play-body" class="quiz-question-card">'+quizQuestionHTML()+'</div><p class="quiz-local-note">'+(s.phase==='feedback'?'Waktu berhenti sebentar saat umpan balik.':s.questions[s.index].mode==='order'?'Susun potongan, lalu periksa jawaban. Soal berikutnya berganti otomatis.':'Pilih satu jawaban. Tidak perlu menekan tombol lanjut.')+'</p></section>'}
function quizRenderPlay(){if(!quizIsActive())return;const el=document.querySelector('.quiz-game');if(el)el.outerHTML=quizPlayScreen();quizSyncLifecycle()}
function quizResultScreen(){const s=quizSession;if(!s)return quizMenu();const completed=s.status==='completed';return '<section class="quiz-result"><span class="quiz-result-flower" aria-hidden="true">'+(completed?'✿':'🌱')+'</span><span class="quiz-eyebrow">'+(completed?'SESI SELESAI':s.reason==='abandoned'?'SESI DIHENTIKAN':'GAME OVER')+'</span><h1>'+(completed?'Satu latihan lagi, satu langkah maju.':s.reason==='lives'?'Nyawamu habis.':s.reason==='time'?'Waktunya habis.':'Sampai jumpa di latihan berikutnya.')+'</h1><p>Jawabanmu bisa jadi bekal untuk latihan selanjutnya.</p><div class="quiz-result-score"><strong>'+s.correct+'<small>/ '+s.questions.length+'</small></strong><span>jawaban benar</span></div><div class="quiz-result-stats"><div><b>'+s.responses.length+'</b><span>terjawab</span></div><div><b>'+s.responses.filter(r=>!r.correct).length+'</b><span>salah</span></div><div><b>'+s.lives+'</b><span>nyawa tersisa</span></div></div><div class="quiz-result-actions"><button class="primary" onclick="quizRepeat()">Latihan lagi ↻</button><button class="chip" onclick="quizMove(\'menu\',true)">Pilih materi lain</button><button class="chip" onclick="showPage(\'Riwayat\')">Lihat riwayat →</button></div><section class="quiz-review"><h2>Mari lihat kembali.</h2>'+(s.responses.length?s.responses.map((r,i)=>'<details><summary><span class="'+(r.correct?'correct-mark':'wrong-mark')+'">'+(r.correct?'✓':'×')+'</span><b>Soal '+(i+1)+' · '+esc(QUIZ_TYPES[r.type].name)+'</b><small>'+(r.correct?'Benar':'Belum tepat')+'</small></summary><div><p>'+esc(r.display)+'</p><p>Jawabanmu: <b>'+esc(r.chosen)+'</b></p><p>Jawaban tepat: <b>'+esc(r.answer)+'</b></p><p>'+esc(r.explanation)+'</p></div></details>').join(''):'<p>Belum ada jawaban pada sesi ini.</p>')+'</section></section>'}
function quizRepeat(){quizState.config=JSON.parse(JSON.stringify(quizSession.config));if(quizState.config.type==='kana')quizState.config.letters=quizExpandKanaSelection(quizState.config);quizMove('confirm',true);if(['bunpo','mixed'].includes(quizState.config.type))quizEnsureBank()}
function quizGuard(action){if(!quizIsActive())return false;if(quizExitAction)return true;quizExitAction=action;modal('<div class="quiz-exit"><span aria-hidden="true">🌱</span><h2>Akhiri latihan ini?</h2><p>Waktu tetap berjalan. Jika keluar, sesi dicatat sebagai dihentikan.</p><button class="primary" onclick="quizCancelExit()">Lanjutkan kuis</button><button class="chip" onclick="quizConfirmExit()">Akhiri kuis</button></div>','Akhiri latihan');return true}
function quizCancelExit(){quizExitAction=null;closeModal()}
function quizConfirmExit(){const action=quizExitAction;quizExitAction=null;closeModal();quizFinish('abandoned');if(action)action()}
function quizHandlePop(route){if(!quizIsActive())return false;history.pushState(appRoute(),'');if(document.querySelector('.modal')){quizCancelExit();return true}quizGuard(()=>history.back());return true}
function quizScreen(){const v=quizState.view,c=quizState.config;if(v==='menu')return quizMenu();if(v==='script')return quizHeader('Pilih jenis huruf.','Setelah ini, pilih huruf yang ingin kamu uji.')+'<div class="quiz-type-grid">'+[['Hiragana','あ'],['Katakana','ア']].map(([n,jp])=>'<button class="quiz-type quiz-lavender" onclick="quizSelectScript(\''+n+'\')"><span class="quiz-type-symbol">'+jp+'</span><div><h2>'+n+'</h2><p>Seion, Yōon, Dakuten, Handakuten</p></div><span>→</span></button>').join('')+'</div>';if(v==='letters')return quizLettersScreen();if(v==='mode')return quizModeScreen();if(v==='categories')return quizCategoriesScreen();if(v==='subs')return quizSubsScreen();if(v==='pages')return quizPagesScreen();if(v==='confirm')return quizConfirmScreen();if(v==='play')return quizPlayScreen();if(v==='result')return quizResultScreen();return quizMenu()}
window.addEventListener('visibilitychange',()=>quizTick());
